"""Small helpers shared by the migrations, so each table definition stays short.

Conventions from docs/DATA-MODEL.md that every table follows:
  * the primary key is a UUID (generated by PostgreSQL itself);
  * every table has created_at and updated_at;
  * there is no password column anywhere (Firebase holds passwords).
"""

import sqlalchemy as sa
from alembic import op
from sqlalchemy.dialects import postgresql

UUID = postgresql.UUID(as_uuid=True)


def id_col() -> sa.Column:
    """UUID primary key. gen_random_uuid() is built into PostgreSQL 13+."""
    return sa.Column(
        "id", UUID, primary_key=True, server_default=sa.text("gen_random_uuid()")
    )


def timestamps() -> list[sa.Column]:
    """created_at / updated_at. A trigger (see 0001) keeps updated_at fresh."""
    return [
        sa.Column(
            "created_at",
            sa.DateTime(timezone=True),
            nullable=False,
            server_default=sa.text("now()"),
        ),
        sa.Column(
            "updated_at",
            sa.DateTime(timezone=True),
            nullable=False,
            server_default=sa.text("now()"),
        ),
    ]


def fk(name: str, target: str, *, ondelete: str, nullable: bool = False) -> sa.Column:
    """A UUID foreign-key column. `ondelete` is always explicit so privacy rules are visible."""
    return sa.Column(
        name, UUID, sa.ForeignKey(target, ondelete=ondelete), nullable=nullable
    )


def one_of(column: str, values: list[str], name: str) -> sa.CheckConstraint:
    """CHECK constraint standing in for an enum (easier to change than a PG enum type)."""
    listed = ", ".join(f"'{v}'" for v in values)
    return sa.CheckConstraint(f"{column} IN ({listed})", name=name)


def create_table(name: str, *items) -> None:
    """create_table + the updated_at trigger, so no table can forget either."""
    op.create_table(name, *items, *timestamps())
    op.execute(
        f"CREATE TRIGGER trg_{name}_updated_at BEFORE UPDATE ON {name} "
        "FOR EACH ROW EXECUTE FUNCTION set_updated_at()"
    )


def drop_table(name: str) -> None:
    op.drop_table(name)  # dropping a table drops its trigger too
